#include <stdio.h>
#include <stdlib.h>

/* Node structure */
typedef struct ListNode {
    int data;
    struct ListNode *next;
} ListNode;

/* Reversal function using an integer array */
void reverseList(int *head, int *tail) {
    int prev = NULL;
    int curr = 0;

    while (curr != NULL) {
        /* Move current pointer forward */
        curr = head[curr];
        if (prev != NULL) {
            /* Swap prev and curr */
            ListNode *tmp = prev->next;
            prev->next = curr;
            curr->next = tmp;
        }
        prev = curr;
    }

    /* Reverse the linked list */
    ListNode *newHead = NULL;
    ListNode *newTail = NULL;

    /* Copy tail's value back to newHead */
    if (tail != NULL) {
        newHead = tail;
        newTail = newHead->next;
    } else {
        newHead = newTail = NULL;
    }

    /* Build reversed list from tail to head */
    ListNode *current = newTail;
    while (current != NULL) {
        ListNode *temp = current->next;
        current->next = newHead;
        newHead = temp;
        current = newHead;
    }

    /* Link original head to the end of the reversed list */
    newHead->next = newTail;
    newTail->next = NULL;
}

/* Helper to create a new ListNode */
ListNode *createNode(int data) {
    ListNode *node = malloc(sizeof(ListNode));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

/* Create a dummy head for easier linking */
ListNode *createDummyHead() {
    ListNode *dummy = malloc(sizeof(ListNode));
    if (!dummy) return NULL;
    dummy->data = 0;
    dummy->next = NULL;
    return dummy;
}

/* Main function: reverses a given linked list */
void reverseList(int *head, int *tail) {
    if (head == NULL || tail == NULL) {
        return;
    }

    reverseList(head, tail);
    reverseList(tail, NULL);
}

