    println!("Is 4 prime? {}", is_prime(4)); // false
    println!("Is 9 prime? {}", is_prime(9)); // false
    println!("Is 2 prime? {}", is_prime(2)); // true
    println!("Is 10 prime? {}", is_prime(10)); // false
}
